{
  "query": {
    "bool": {
      "filter": [ { "term": { "status": "published" } } ],
      "must":   [ { "match": { "title": "wireless headphones" } } ]
    }
  }
}

{
  "query": { "match": { "category": "electronics" } },
  "aggs": {
    "avg_price": { "avg": { "field": "price" } },
    "by_brand": { "terms": { "field": "brand.keyword" } }
  }
}

"suggest": {
  "headphones-suggest": {
    "prefix": "wire",
    "completion": { "field": "suggest" }
  }
}
